    errorCodes: [429, 500, 502, 503, 504],
    supportsStreaming: true,
  },

  // TIER 3: Additional Free Tier (Priority 9-13)
  {
    name: 'Perplexity',
    priority: 9,
    enabled: true,
    baseUrl: 'https://api.perplexity.ai',
    apiKeyEnv: 'VITE_PERPLEXITY_API_KEY',
